        JTextField subcategory = new JTextField(boss.getSubcategory());
        JTextField npcIds = new JTextField(formatNpcIds(boss.getNpcIds()));
        JTextArea notes = new JTextArea(boss.getNotes(), 5, 24);
        notes.setLineWrap(true);
        notes.setWrapStyleWord(true);

        JPanel form = new JPanel();
        form.setLayout(new BoxLayout(form, BoxLayout.Y_AXIS));

        form.add(new JLabel("Boss name"));
        form.add(name);
        form.add(Box.createVerticalStrut(6));
        form.add(new JLabel("Category"));
        form.add(category);
        form.add(Box.createVerticalStrut(6));
        form.add(new JLabel("Subcategory"));
        form.add(subcategory);
        form.add(Box.createVerticalStrut(6));
        form.add(new JLabel("NPC IDs (comma-separated)"));
        form.add(npcIds);
        form.add(Box.createVerticalStrut(6));
        form.add(new JLabel("Notes"));
        form.add(new JScrollPane(notes));

        int result = JOptionPane.showConfirmDialog(
            this,
            form,
            "Edit " + boss.getDisplayName(),
            JOptionPane.OK_CANCEL_OPTION,
            JOptionPane.PLAIN_MESSAGE);

        if (result == JOptionPane.OK_OPTION)
        {
            try
            {
                store.updateBoss(
                    boss.getId(),
                    name.getText(),
                    category.getText(),
                    subcategory.getText(),
                    parseNpcIds(npcIds.getText()),
                    notes.getText());
            }
            catch (IllegalArgumentException ex)
            {
                JOptionPane.showMessageDialog(
                    this,
                    ex.getMessage(),
                    "Boss KD Tracker",
                    JOptionPane.ERROR_MESSAGE);
            }
        }
    }

    private void showHistory(BossProfile boss)
    {
        List<TrackerEvent> events = store.getEventsForBoss(boss.getId());

        JTextArea area = new JTextArea(18, 42);
        area.setEditable(false);

        if (events.isEmpty())
        {
            area.setText("No events recorded yet.");
        }
        else
        {
            StringBuilder text = new StringBuilder();

            for (TrackerEvent event : events)
            {
                text.append(EVENT_TIME_FORMAT.format(event.getTimestamp()))
                    .append("  ")
                    .append(event.getType())
                    .append("  ")
                    .append(event.getAmount() > 0 ? "+" : "")
                    .append(event.getAmount())
                    .append("  [")
                    .append(event.getSource())
                    .append("]");

                if (!event.getNote().isEmpty())
                {
                    text.append("  ").append(event.getNote());
                }

                text.append(System.lineSeparator());
            }

            area.setText(text.toString());
            area.setCaretPosition(0);
        }

        JOptionPane.showMessageDialog(
            this,
            new JScrollPane(area),
            boss.getDisplayName() + " - Event History",
            JOptionPane.PLAIN_MESSAGE);
    }

    private void showBossCatalog()
    {
        List<BossDefinition> definitions = BossDefinitionRegistry.getAll();

        StringBuilder text = new StringBuilder();
        text.append("Built-in boss definitions: ")
            .append(definitions.size())
            .append(System.lineSeparator())
            .append(System.lineSeparator());

        for (BossDefinition definition : definitions)
        {
            text.append(definition.getDisplayName())
                .append("  —  ")
                .append(formatNpcIds(
                    java.util.Arrays.stream(definition.getNpcIds())
                        .boxed()
                        .collect(Collectors.toList())))
                .append(System.lineSeparator());
        }

        JTextArea area = new JTextArea(24, 46);
        area.setEditable(false);
        area.setText(text.toString());
        area.setCaretPosition(0);

        JOptionPane.showMessageDialog(
            this,
            new JScrollPane(area),
            "Boss NPC ID Catalog",
            JOptionPane.PLAIN_MESSAGE);
    }

    private static List<Integer> parseNpcIds(String text)
    {
        List<Integer> result = new ArrayList<>();

        if (text == null || text.trim().isEmpty())
        {
            return result;
        }

        for (String token : text.split("[,;\\\\s]+"))
        {
            if (token.trim().isEmpty())
            {
                continue;
            }

            try
            {
                int id = Integer.parseInt(token.trim());

                if (id < 0)
                {
                    throw new NumberFormatException();
                }

                if (!result.contains(id))
                {
                    result.add(id);
                }
            }
            catch (NumberFormatException ex)
            {
                throw new IllegalArgumentException(
                    "Invalid NPC ID: " + token + ". Use numeric IDs separated by commas.");
            }
        }

        return result;
    }

    private static String formatNpcIds(List<Integer> ids)
    {
        if (ids == null || ids.isEmpty())
        {
            return "None";
        }

        return ids.stream()
            .map(String::valueOf)
            .collect(Collectors.joining(", "));
    }

    private boolean confirmCorrection(String message)
    {
        if (!config.confirmCorrections())
        {
            return true;
        }

        return JOptionPane.showConfirmDialog(
            this,
            message,
            "Boss KD Tracker",
            JOptionPane.YES_NO_OPTION,
            JOptionPane.QUESTION_MESSAGE) == JOptionPane.YES_OPTION;
    }

    private static String yesNo(boolean value)
    {
        return value ? "Yes" : "No";
    }

    private static Color statusColor(SyncStatus status)
    {
        switch (status)
        {
            case AUTO:
            case SYNCED:
                return new Color(92, 184, 92);

            case PARTIAL:
                return new Color(240, 173, 78);

            case DISABLED:
                return new Color(180, 180, 180);

            case MANUAL:
            default:
                return new Color(91, 192, 222);
        }
    }
}

package com.bossdeathtracker;

import com.google.inject.Provides;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.List;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.InteractingChanged;
import net.runelite.api.events.NpcChanged;
import net.runelite.api.events.NpcSpawned;
import net.runelite.client.chat.ChatCommandManager;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ChatInput;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@PluginDescriptor(
    name = "Boss Death Tracker",
    description = "Track boss deaths and kills with automatic death attribution and manual boss support",
    tags = {"boss", "death", "tracker", "pvm", "kills", "statistics"}
)
public class BossDeathTrackerPlugin extends Plugin
{
    private static final String KD_COMMAND = "!KD";

    private static final Logger log =
        LoggerFactory.getLogger(BossDeathTrackerPlugin.class);

    @Inject
    private Client client;

    @Inject
    private ClientToolbar clientToolbar;

    @Inject
    private ChatCommandManager chatCommandManager;

    @Inject
    private BossDeathTrackerStore store;

    @Inject
    private BossDeathTrackerConfig config;

    @Inject
    private ConfigManager configManager;

    private final BossEncounterTracker encounterTracker =
        new BossEncounterTracker();

    private BossDeathTrackerPanel panel;
    private NavigationButton navigationButton;
    private int gameTickCounter;
    private String lastPanelActiveBossId;

    @Override
    protected void startUp()
    {
        encounterTracker.reset();
        gameTickCounter = 0;

        panel = new BossDeathTrackerPanel(store, config, configManager);

        navigationButton = NavigationButton.builder()
            .tooltip("Boss Death Tracker")
            .icon(createIcon())
            .priority(5)
            .panel(panel)
            .build();

        clientToolbar.addNavigation(navigationButton);

        chatCommandManager.registerCommand(
            KD_COMMAND,
            (chatMessage, message) -> { },
            this::handleKdCommandInput);

        store.loadAsync(error ->
            SwingUtilities.invokeLater(() ->
            {
                if (error != null)
                {
                    log.warn("Boss Death Tracker data load completed with an error", error);
                }

                BossDeathTrackerStore.HistoricalKillSyncResult syncResult =
                    store.syncRuneLiteKillCounts(configManager);

                if (syncResult.getBossesUpdated() > 0)
                {
                    log.info(
                        "Synchronized {} historical kills across {} bosses",
                        syncResult.getKillsImported(),
                        syncResult.getBossesUpdated());
                }

                if (panel != null)
                {
                    panel.refresh();
                }
            }));
    }

    @Override
    protected void shutDown()
    {
        chatCommandManager.unregisterCommand(KD_COMMAND);
        encounterTracker.reset();

        if (navigationButton != null)
        {
            clientToolbar.removeNavigation(navigationButton);
            navigationButton = null;
        }

        panel = null;
        store.shutdown();
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (!"killcount".equals(event.getGroup()))
        {
            return;
        }

        BossDeathTrackerStore.HistoricalKillSyncResult result =
            store.syncRuneLiteKillCounts(configManager);

        if (result.getBossesUpdated() > 0)
        {
            log.debug(
                "RuneLite killcount cache changed; imported {} kills across {} bosses",
                result.getKillsImported(),
                result.getBossesUpdated());

            refreshPanel();
        }
    }

    @Subscribe
    public void onNpcSpawned(NpcSpawned event)
    {
        Player localPlayer = client.getLocalPlayer();

        if (localPlayer == null)
        {
            return;
        }

        encounterTracker.observeNpc(
            event.getNpc(),
            localPlayer,
            store,
            gameTickCounter);

        syncEncounterToPanel();
    }

    @Subscribe
    public void onNpcChanged(NpcChanged event)
    {
        Player localPlayer = client.getLocalPlayer();

        if (localPlayer == null)
        {
            return;
        }

        encounterTracker.observeNpcChanged(
            event.getNpc(),
            localPlayer,
            store,
            gameTickCounter);

        syncEncounterToPanel();
    }

    @Subscribe
    public void onInteractingChanged(InteractingChanged event)
    {
        Player localPlayer = client.getLocalPlayer();

        if (localPlayer == null)
        {
            return;
        }

        encounterTracker.observeInteraction(
            event.getSource(),
            event.getTarget(),
            localPlayer,
            store,
            gameTickCounter);

        syncEncounterToPanel();
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        gameTickCounter++;
        encounterTracker.onGameTick(gameTickCounter);

        // Refresh the current interaction each game tick. This handles cases
        // where the plugin was enabled after an NPC had already spawned.
        Player localPlayer = client.getLocalPlayer();

        if (localPlayer == null)
        {
            return;
        }

        if (localPlayer.getInteracting() instanceof NPC)
        {
            encounterTracker.observeNpc(
                (NPC) localPlayer.getInteracting(),
                localPlayer,
                store,
                gameTickCounter);

            syncEncounterToPanel();
        }
    }

    @Subscribe
    public void onActorDeath(ActorDeath event)
    {
        Player localPlayer = client.getLocalPlayer();

        if (localPlayer == null)
        {
            return;
        }

        // Local-player death attribution.
        if (event.getActor() == localPlayer)
        {
            if (!config.automaticDeaths())
            {
                encounterTracker.reset();
                return;
            }

            encounterTracker.getDeathAttribution(gameTickCounter)
                .ifPresent(attribution ->
                {
                    String note =
                        "Automatically attributed to "
                            + attribution.getBossName()
                            + " (NPC ID "
                            + attribution.getNpcId()
                            + ")";

                    store.addAutomaticDeath(
                        attribution.getBossId(),
                        note);
                    store.markDeathVerified(attribution.getBossId());

                    log.debug(
                        "Automatically recorded player death to {} (NPC ID {})",
                        attribution.getBossName(),
                        attribution.getNpcId());

                    refreshPanel();

                    // Require a new interaction before another death/kill can
                    // be attributed to this encounter.
                    encounterTracker.reset();
                    syncEncounterToPanel();
                });

            return;
        }

        // Boss kill attribution. An NPC death only counts when that NPC maps
        // to the exact boss profile currently held by the encounter tracker.
        if (event.getActor() instanceof NPC && config.automaticKills())
        {
            NPC deadNpc = (NPC) event.getActor();

            encounterTracker.getKillAttribution(
                deadNpc,
                store,
                gameTickCounter)
                .ifPresent(attribution ->
                {
                    String note =
                        "Automatically recorded boss kill for "
                            + attribution.getBossName()
                            + " (NPC ID "
                            + attribution.getNpcId()
                            + ")";

                    store.addAutomaticKill(
                        attribution.getBossId(),
                        note);
                    store.markKillVerified(attribution.getBossId());

                    log.debug(
                        "Automatically recorded boss kill for {} (NPC ID {})",
                        attribution.getBossName(),
                        attribution.getNpcId());

                    refreshPanel();

                    // A completed kill closes this encounter. Any subsequent
                    // fight must establish a fresh interaction.
                    encounterTracker.reset();
                    syncEncounterToPanel();
                });
        }
    }

    private boolean handleKdCommandInput(ChatInput chatInput, String message)
    {
        String query = message == null ? "" : message.trim();

        if (query.length() >= KD_COMMAND.length()
            && query.regionMatches(true, 0, KD_COMMAND, 0, KD_COMMAND.length()))
        {
            query = query.substring(KD_COMMAND.length()).trim();
        }

        if (query.isEmpty())
        {
            client.addChatMessage(
                ChatMessageType.GAMEMESSAGE,
                "",
                "Boss KD Tracker: Usage: !KD <boss name>",
                null);
            return true;
        }

        List<BossProfile> matches = store.searchBosses(query);
        BossProfile selected = null;

        for (BossProfile boss : matches)
        {
            if (boss.getDisplayName().equalsIgnoreCase(query))
            {
                selected = boss;
                break;
            }
        }

        if (selected == null)
        {
            if (matches.size() == 1)
            {
                selected = matches.get(0);
            }
            else if (matches.isEmpty())
            {
                client.addChatMessage(
                    ChatMessageType.GAMEMESSAGE,
                    "",
                    "Boss KD Tracker: Boss not found.",
                    null);
                return true;
            }
            else
            {
                client.addChatMessage(
                    ChatMessageType.GAMEMESSAGE,
                    "",
                    "Boss KD Tracker: Multiple boss matches found.",
                    null);
                return true;
            }
        }

        int kills = store.getKillCount(selected.getId());
        int deaths = store.getDeathCount(selected.getId());

        String result =
            selected.getDisplayName()
                + " - Kills: " + kills
                + " | Deaths: " + deaths;

        // The player manually enters !KD. Consume that command and render the
        // result locally; never populate, rewrite, or automatically send chat.
        client.addChatMessage(
            ChatMessageType.GAMEMESSAGE,
            "",
            result,
            null);

        return true;
    }

    private void syncEncounterToPanel()
    {
        String activeBossId = encounterTracker.getActiveBossId();

        if (!java.util.Objects.equals(lastPanelActiveBossId, activeBossId))
        {
            lastPanelActiveBossId = activeBossId;

            if (activeBossId != null)
            {
                store.markEncounterVerified(activeBossId);
            }

            if (panel != null)
            {
                panel.setActiveBoss(activeBossId);
            }
        }
    }

    private void refreshPanel()
    {
        if (panel != null)
        {
            panel.refresh();
        }
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        GameState state = event.getGameState();

        if (state == GameState.LOGIN_SCREEN
            || state == GameState.HOPPING
            || state == GameState.CONNECTION_LOST)
        {
            encounterTracker.reset();
            syncEncounterToPanel();
        }
    }

    @Provides
    BossDeathTrackerConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(BossDeathTrackerConfig.class);
    }

    private static BufferedImage createIcon()
    {
        BufferedImage image =
            new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);

        Graphics2D g = image.createGraphics();

        try
        {
            g.setRenderingHint(
                RenderingHints.KEY_ANTIALIASING,
                RenderingHints.VALUE_ANTIALIAS_ON);

            g.setColor(new Color(220, 220, 220));
            g.fillOval(2, 1, 12, 11);

            g.setColor(new Color(45, 45, 45));
            g.fillOval(5, 5, 2, 2);
            g.fillOval(9, 5, 2, 2);
            g.fillRect(7, 8, 2, 2);

            g.setColor(new Color(220, 220, 220));
            g.fillRect(4, 10, 8, 5);

            g.setColor(new Color(45, 45, 45));
            g.drawLine(6, 11, 6, 14);
            g.drawLine(9, 11, 9, 14);
        }
        finally
        {
            g.dispose();
        }

        return image;
    }
}

package com.bossdeathtracker;

import com.google.gson.Gson;
import com.google.inject.Inject;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import java.util.Optional;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.function.Consumer;
import net.runelite.client.RuneLite;
import net.runelite.client.config.ConfigManager;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class BossDeathTrackerStore
{
    private static final Logger log = LoggerFactory.getLogger(BossDeathTrackerStore.class);

    private static final Path DATA_DIR =
        RuneLite.RUNELITE_DIR.toPath().resolve("boss-death-tracker");

    private static final Path DATA_FILE = DATA_DIR.resolve("tracker-data.json");
    private static final Path TEMP_FILE = DATA_DIR.resolve("tracker-data.json.tmp");

    private final Gson gson;
    private ExecutorService ioExecutor;

    private TrackerData data = new TrackerData();

    @Inject
    public BossDeathTrackerStore(Gson gson)
    {
        this.gson = gson;
    }

    public void loadAsync(Consumer<Throwable> completion)
    {
        ensureExecutor().execute(() ->
        {
            Throwable error = null;

            try
            {
                Files.createDirectories(DATA_DIR);

                if (Files.exists(DATA_FILE))
                {
                    String json = Files.readString(DATA_FILE, StandardCharsets.UTF_8);
                    TrackerData loaded = gson.fromJson(json, TrackerData.class);

                    synchronized (this)
                    {
                        data = loaded == null ? new TrackerData() : loaded;
                        seedBuiltInDefinitionsLocked();
                    }
                }
                else
                {
                    synchronized (this)
                    {
                        seedBuiltInDefinitionsLocked();
                    }
                    queueSave();
                }
            }
            catch (Exception ex)
            {
                error = ex;
                log.warn("Unable to load Boss Death Tracker data", ex);
            }

            if (completion != null)
            {
                completion.accept(error);
            }
        });
    }

    public synchronized List<BossProfile> getBosses()
    {
        List<BossProfile> result = new ArrayList<>(data.getBosses());
        result.sort(Comparator.comparing(
            BossProfile::getDisplayName,
            String.CASE_INSENSITIVE_ORDER));
        return result;
    }

    public synchronized List<BossProfile> searchBosses(String query)
    {
        if (query == null || query.trim().isEmpty())
        {
            return getBosses();
        }

        String needle = query.trim().toLowerCase(Locale.ROOT);
        List<BossProfile> result = new ArrayList<>();

        for (BossProfile boss : data.getBosses())
        {
            String npcIdText = boss.getNpcIds()
                .stream()
                .map(String::valueOf)
                .collect(java.util.stream.Collectors.joining(" "));

            String haystack =
                (safe(boss.getDisplayName()) + " " +
                 safe(boss.getCategory()) + " " +
                 safe(boss.getSubcategory()) + " " +
                 npcIdText).toLowerCase(Locale.ROOT);

            if (haystack.contains(needle))
            {
                result.add(boss);
            }
        }

        result.sort(Comparator.comparing(
            BossProfile::getDisplayName,
            String.CASE_INSENSITIVE_ORDER));

        return result;
    }

