        int... npcIds)
    {
        BossDefinition definition =
            new BossDefinition(key, displayName, category, subcategory, npcIds);

        BY_KEY.put(key, definition);

        for (int npcId : npcIds)
        {
            // Keep the first registration if an ID is ever intentionally shared.
            BY_NPC_ID.putIfAbsent(npcId, definition);
        }
    }

    public static List<BossDefinition> getAll()
    {
        return Collections.unmodifiableList(new ArrayList<>(BY_KEY.values()));
    }

    public static Optional<BossDefinition> findByKey(String key)
    {
        return Optional.ofNullable(BY_KEY.get(key));
    }

    public static Optional<BossDefinition> findByNpcId(int npcId)
    {
        return Optional.ofNullable(BY_NPC_ID.get(npcId));
    }
}

package com.bossdeathtracker;

import java.util.Optional;
import net.runelite.api.Actor;
import net.runelite.api.NPC;
import net.runelite.api.Player;

/**
 * Holds short-lived encounter attribution state.
 *
 * The tracker does not itself subscribe to RuneLite events. RuneLite event
 * subscribers remain in BossDeathTrackerPlugin and forward relevant events
 * here.
 */
public class BossEncounterTracker
{
    // 100 game ticks is about one minute. This prevents an old encounter from
    // receiving a death after the player has clearly left the fight.
    private static final int ENCOUNTER_TIMEOUT_TICKS = 100;

    private String activeBossId;
    private String activeBossName;
    private int activeBossNpcId = -1;
    private int lastConfirmedTick = -1;

    public void reset()
    {
        activeBossId = null;
        activeBossName = null;
        activeBossNpcId = -1;
        lastConfirmedTick = -1;
    }

    public void observeNpc(
        NPC npc,
        Player localPlayer,
        BossDeathTrackerStore store,
        int currentTick)
    {
        if (npc == null || localPlayer == null)
        {
            return;
        }

        Optional<BossProfile> boss = store.findBossByNpcId(npc.getId());

        if (!boss.isPresent())
        {
            return;
        }

        Actor npcTarget = npc.getInteracting();
        Actor playerTarget = localPlayer.getInteracting();

        // A recognized boss becomes active when either side is explicitly
        // interacting with the other. Merely spawning nearby is not enough.
        if (npcTarget == localPlayer || playerTarget == npc)
        {
            activate(boss.get(), npc.getId(), currentTick);
        }
    }

    public void observeInteraction(
        Actor source,
        Actor target,
        Player localPlayer,
        BossDeathTrackerStore store,
        int currentTick)
    {
        if (source == null || target == null || localPlayer == null)
        {
            return;
        }

        NPC npc = null;

        if (source == localPlayer && target instanceof NPC)
        {
            npc = (NPC) target;
        }
        else if (target == localPlayer && source instanceof NPC)
        {
            npc = (NPC) source;
        }

        if (npc == null)
        {
            return;
        }

        Optional<BossProfile> boss = store.findBossByNpcId(npc.getId());

        if (boss.isPresent())
        {
            activate(boss.get(), npc.getId(), currentTick);
        }
    }

    public void observeNpcChanged(
        NPC npc,
        Player localPlayer,
        BossDeathTrackerStore store,
        int currentTick)
    {
        if (npc == null || localPlayer == null)
        {
            return;
        }

        Optional<BossProfile> changedBoss = store.findBossByNpcId(npc.getId());

        if (!changedBoss.isPresent())
        {
            return;
        }

        BossProfile boss = changedBoss.get();

        // Phase/form changes commonly alter an NPC ID. Preserve encounter
        // ownership if the changed NPC belongs to the same boss definition,
        // or if it is interacting with the local player.
        if (boss.getId().equals(activeBossId)
            || npc.getInteracting() == localPlayer
            || localPlayer.getInteracting() == npc)
        {
            activate(boss, npc.getId(), currentTick);
        }
    }

    public void onGameTick(int currentTick)
    {
        if (activeBossId == null || lastConfirmedTick < 0)
        {
            return;
        }

        if (currentTick - lastConfirmedTick > ENCOUNTER_TIMEOUT_TICKS)
        {
            reset();
        }
    }

    public String getActiveBossId()
    {
        return activeBossId;
    }

    public Optional<Attribution> getKillAttribution(
        NPC deadNpc,
        BossDeathTrackerStore store,
        int currentTick)
    {
        if (deadNpc == null || activeBossId == null || lastConfirmedTick < 0)
        {
            return Optional.empty();
        }

        if (currentTick - lastConfirmedTick > ENCOUNTER_TIMEOUT_TICKS)
        {
            reset();
            return Optional.empty();
        }

        Optional<BossProfile> deadBoss = store.findBossByNpcId(deadNpc.getId());

        if (!deadBoss.isPresent() || !deadBoss.get().getId().equals(activeBossId))
        {
            return Optional.empty();
        }

        return Optional.of(new Attribution(
            activeBossId,
            activeBossName,
            deadNpc.getId()));
    }

    public Optional<Attribution> getDeathAttribution(int currentTick)
    {
        if (activeBossId == null || lastConfirmedTick < 0)
        {
            return Optional.empty();
        }

        if (currentTick - lastConfirmedTick > ENCOUNTER_TIMEOUT_TICKS)
        {
            reset();
            return Optional.empty();
        }

        return Optional.of(new Attribution(
            activeBossId,
            activeBossName,
            activeBossNpcId));
    }

    private void activate(BossProfile boss, int npcId, int currentTick)
    {
        activeBossId = boss.getId();
        activeBossName = boss.getDisplayName();
        activeBossNpcId = npcId;
        lastConfirmedTick = currentTick;
    }

    public static final class Attribution
    {
        private final String bossId;
        private final String bossName;
        private final int npcId;

        private Attribution(String bossId, String bossName, int npcId)
        {
            this.bossId = bossId;
            this.bossName = bossName;
            this.npcId = npcId;
        }

        public String getBossId()
        {
            return bossId;
        }

        public String getBossName()
        {
            return bossName;
        }

        public int getNpcId()
        {
            return npcId;
        }
    }
}

package com.bossdeathtracker;

import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.UUID;

public class BossProfile
{
    private String id;
    private String definitionKey;
    private String displayName;
    private String category;
    private String subcategory;
    private boolean customBoss;
    private SyncStatus syncStatus;
    private List<Integer> npcIds = new ArrayList<>();
    private boolean encounterVerified;
    private boolean deathVerified;
    private boolean killVerified;
    private String notes;
    private Instant createdAt;
    private Instant updatedAt;

    public BossProfile()
    {
        // Required for Gson.
    }

    public static BossProfile createManual(
        String displayName,
        String category,
        String subcategory,
        List<Integer> npcIds,
        String notes)
    {
        BossProfile boss = new BossProfile();
        boss.id = UUID.randomUUID().toString();
        boss.displayName = displayName;
        boss.category = category;
        boss.subcategory = subcategory;
        boss.customBoss = true;
        boss.syncStatus =
            npcIds == null || npcIds.isEmpty() ? SyncStatus.MANUAL : SyncStatus.PARTIAL;
        boss.npcIds = copyIds(npcIds);
        boss.notes = notes == null ? "" : notes;
        boss.createdAt = Instant.now();
        boss.updatedAt = boss.createdAt;
        return boss;
    }

    public static BossProfile createFromDefinition(BossDefinition definition)
    {
        BossProfile boss = new BossProfile();
        boss.id = UUID.randomUUID().toString();
        boss.definitionKey = definition.getKey();
        boss.displayName = definition.getDisplayName();
        boss.category = definition.getCategory();
        boss.subcategory = definition.getSubcategory();
        boss.customBoss = false;

        for (int npcId : definition.getNpcIds())
        {
            boss.npcIds.add(npcId);
        }

        // IDs are known, but encounter/death automation is intentionally not
        // enabled in this build yet.
        boss.syncStatus = SyncStatus.PARTIAL;
        boss.notes = "";
        boss.createdAt = Instant.now();
        boss.updatedAt = boss.createdAt;
        return boss;
    }

    public String getId()
    {
        return id;
    }

    public String getDefinitionKey()
    {
        return definitionKey;
    }

    public String getDisplayName()
    {
        return displayName;
    }

    public String getCategory()
    {
        return category;
    }

    public String getSubcategory()
    {
        return subcategory;
    }

    public boolean isCustomBoss()
    {
        return customBoss;
    }

    public SyncStatus getSyncStatus()
    {
        return syncStatus == null ? SyncStatus.MANUAL : syncStatus;
    }

    public List<Integer> getNpcIds()
    {
        if (npcIds == null)
        {
            npcIds = new ArrayList<>();
        }

        return Collections.unmodifiableList(npcIds);
    }

    public boolean hasNpcId(int npcId)
    {
        return getNpcIds().contains(npcId);
    }

    public boolean isEncounterVerified()
    {
        return encounterVerified;
    }

    public boolean isDeathVerified()
    {
        return deathVerified;
    }

    public boolean isKillVerified()
    {
        return killVerified;
    }

    public String getNotes()
    {
        return notes == null ? "" : notes;
    }

    public Instant getCreatedAt()
    {
        return createdAt;
    }

    public Instant getUpdatedAt()
    {
        return updatedAt;
    }

    public void setDisplayName(String displayName)
    {
        this.displayName = displayName;
        touch();
    }

    public void setCategory(String category)
    {
        this.category = category;
        touch();
    }

    public void setSubcategory(String subcategory)
    {
        this.subcategory = subcategory;
        touch();
    }

    public void setNpcIds(List<Integer> ids)
    {
        npcIds = copyIds(ids);

        if (customBoss && !npcIds.isEmpty() && getSyncStatus() == SyncStatus.MANUAL)
        {
            syncStatus = SyncStatus.PARTIAL;
        }

        touch();
    }

    public void applyDefinition(BossDefinition definition)
    {
        definitionKey = definition.getKey();
        displayName = definition.getDisplayName();
        category = definition.getCategory();
        subcategory = definition.getSubcategory();

        npcIds = new ArrayList<>();
        for (int npcId : definition.getNpcIds())
        {
            npcIds.add(npcId);
        }

        syncStatus = SyncStatus.SYNCED;
        touch();
    }

    public void markEncounterVerified()
    {
        encounterVerified = true;
        updateVerificationStatus();
        touch();
    }

    public void markDeathVerified()
    {
        encounterVerified = true;
        deathVerified = true;
        updateVerificationStatus();
        touch();
    }

    public void markKillVerified()
    {
        encounterVerified = true;
        killVerified = true;
        updateVerificationStatus();
        touch();
    }

    private void updateVerificationStatus()
    {
        if (deathVerified && killVerified)
        {
            syncStatus = SyncStatus.AUTO;
        }
        else if (getSyncStatus() == SyncStatus.MANUAL && !getNpcIds().isEmpty())
        {
            syncStatus = SyncStatus.PARTIAL;
        }
    }

    public void setNotes(String notes)
    {
        this.notes = notes == null ? "" : notes;
        touch();
    }

    public void setSyncStatus(SyncStatus syncStatus)
    {
        this.syncStatus = syncStatus;
        touch();
    }

    private void touch()
    {
        updatedAt = Instant.now();
    }

    private static List<Integer> copyIds(List<Integer> ids)
    {
        List<Integer> copy = new ArrayList<>();

        if (ids != null)
        {
            for (Integer id : ids)
            {
                if (id != null && id >= 0 && !copy.contains(id))
                {
                    copy.add(id);
                }
            }
        }

        return copy;
    }
}

package com.bossdeathtracker;

public enum SyncStatus
{
    MANUAL("Manual"),
    PARTIAL("Unverified"),
    SYNCED("Synced"),
    AUTO("Verified"),
    DISABLED("Disabled");

    private final String displayName;

    SyncStatus(String displayName)
    {
        this.displayName = displayName;
    }

    public String getDisplayName()
    {
        return displayName;
    }
}

